def _calculate_total(order):
    total = sum(item["price"] * item["qty"] for item in order["items"])
    if total > 100:
        total *= 0.9
    if order.get("member"):
        total *= 0.95
    return total

def calc(o):
    try:
        return round(_calculate_total(o), 2)
    except (KeyError, TypeError):
        return 0

